SELECT CASE WHEN monthly_fee >= 210 THEN 'high' WHEN monthly_fee >= 52 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, SUM(monthly_fee) AS total_monthly_fee, COUNT(*) AS cnt, SUM(SUM(monthly_fee)) OVER (ORDER BY CASE WHEN monthly_fee >= 210 THEN 'high' WHEN monthly_fee >= 52 THEN 'mid' ELSE 'low' END) AS cumulative_monthly_fee FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 210 THEN 'high' WHEN monthly_fee >= 52 THEN 'mid' ELSE 'low' END
